sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    try {

        var prompts = ["Business Rule", "Script Include function"];
        var setFields = ["script", "script_includes"];


        for (var i = 0; i < prompts.length; i++) {
            (function(index) {

                var prompt = 'For servicenow write a ' + prompts[index] + ' to ' + g_form.getValue('script_name').toString() + ". " +'Please reply back only the script removing all explanations,comments, new line tags or anything which is not supported in servicenow syntax.';

                var getServerResponse = new GlideAjax('x_938076_now_utils.getGeminiResponse');
                getServerResponse.addParam('sysparm_name', 'geminiAutoGenerateScript');
                getServerResponse.addParam('sysparm_prompt', prompt);
                getServerResponse.getXMLAnswer(function(responseAnswer) {
                    var geminiAnswer = JSON.parse(responseAnswer);
                    g_form.setValue(setFields[index], geminiAnswer.answer);
                });

            })(i); // Pass the current index into the IIFE
        }

        //getPromptFields

        // var prompts = [];
        // var setFields = [];


        // var getPromptFields = new GlideAjax('x_938076_now_utils.getGeminiResponse');
        // getPromptFields.addParam('sysparm_name', 'getPromptFields');
        // getPromptFields.addParam('sysparm_prompt', prompt);
        // getPromptFields.getXMLAnswer(responsePromptAnswer)

        // function responsePromptAnswer(response) {
        //     var promptAnswers = response.split("|");

        //     var promptsArr = promptAnswers[0].split(',');
        //     var setFieldArr = promptAnswers[1].split(',');

        //     for (var j = 0; j < promptsArr.length; j++) {

        //         (function(index) {
        //             prompts.push(promptsArr[j] + '');
        //             setFields.push(setFieldArr[j] + '');
        //         })(j); 
        //     }

        //     g_form.addInfoMessage(" prompts " + prompts);
        //     g_form.addInfoMessage(" setFields " + setFields);



        //(function(index) { ... })(i);






    } catch (ex) {
        g_form.addInfoMessage('Error ' + ex);
    }




}
